const a={title:"TripReel - Darmowa Aplikacja Animacji Podróży: Przekształć Zdjęcia w Piękne Filmy",description:"Twórz oszałamiające filmy podróżnicze z animowanymi mapami i trasami lotów. Darmowa aplikacja animacji podróży z mapowaniem trasy globu 3D. Przekształć swoje zdjęcia w piękne filmy podróżnicze automatycznie. Prywatność na pierwszym miejscu, działa offline.",keywords:"aplikacja animacji podróży, aplikacja animacji mapy podróży, aplikacja animacji trasy podróży, aplikacja animacji lotu, twórca filmów podróżniczych, automatyczny film podróżniczy, animowana mapa podróży, animacja trasy lotu, animacja podróży, animacja globu, film podsumowania podróży, zdjęcie na film, najważniejsze momenty podróży, darmowa aplikacja podróży, twórca filmów offline, prywatna aplikacja podróży, film rolki aparatu"},i={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Jak to działa",video:"Wideo",features:"Funkcje",theApp:"Aplikacja"},e={badge:"Zamień zdjęcia w historie podróży",title1:"Twój aparat,",title2:"w pełni wykorzystany",description:"TripReel automatycznie tworzy piękne filmy podróżnicze z lokalizacji Twoich zdjęć. Zobacz, jak Twoje podróże ożywają dzięki wspaniałym animowanym mapom tras i trasomlotów na globusie 3D, zachowując prywatność i bezpieczeństwo Twoich danych.",secure:"100% bezpieczne",worksOffline:"Działa offline",globeAlt:"Animacja globusa TripReel"},o={title:"Jak to działa",subtitle:"Trzy proste kroki do stworzenia idealnego filmu podróżniczego",step1:{title:"Zezwól na dostęp do zdjęć",description:"Przyznaj TripReel dostęp do biblioteki zdjęć. Aplikacja czyta tylko metadane lokalizacji, nic więcej."},step2:{title:"Automatyczne wykrywanie podróży",description:"TripReel analizuje metadane lokalizacji i inteligentnie znajduje Twoje podróże na podstawie dat i miejsc."},step3:{title:"Wygeneruj swoje wideo",description:"Obserwuj, jak Twoja podróż rozwija się na pięknej animacji globusa, gotowa do udostępnienia w mediach społecznościowych."}},t={title:"Zobacz magię w akcji",subtitle:"Odkryj, jak TripReel przekształca Twoją bibliotekę zdjęć w niesamowite filmy podróżnicze",caption:"Tak może wyglądać Twoje finalne wideo podróżnicze"},n={title:"Wszystko, czego potrzebujesz",subtitle:"Potężne funkcje zaprojektowane dla nowoczesnych podróżników",twoTap:{title:"Filmy podróżnicze na dwa kliknięcia",description:"Twórz wspaniałe filmy podróżnicze z biblioteki zdjęć za pomocą tylko dwóch kliknięć. Bez edycji."},smartTrip:{title:"Inteligentne wykrywanie podróży",description:"Automatycznie znajduje i grupuje Twoje podróże, analizując daty i metadane lokalizacji ze zdjęć."},globe:{title:"Piękna animacja globusa",description:"Zobacz, jak Twoja podróż ożywa na wspaniałym globusie 3D pokazującym animowane trasy podróży i trasy lotów na całym świecie."},privacy:{title:"Prywatność przede wszystkim",description:"Wszystko przetwarza się na Twoim urządzeniu. Twoje zdjęcia nigdy nie opuszczają telefonu. Działa w trybie samolotowym."},customStyles:{title:"Własne style",description:"Wybierz spośród wielu stylów globusa i dostosowań, aby pasowały do Twojej estetyki i uczyniły każdy film wyjątkowym."},manualControl:{title:"Ręczna kontrola",description:"Możesz ręcznie dodawać zupełnie nowe podróże, jeśli usługi lokalizacji nie były włączone na Twoim urządzeniu."}},r={title:"Kreatywne pomysły na wideo",subtitle:"Zainspiruj się tym, co możesz stworzyć za pomocą TripReel. Od szybkich wypadów weekendowych po roczne przygody, twórz wspaniałe filmy podróżnicze dla każdej podróży.",description:"Czy tworzysz animację mapy podróży, dokumentujesz trasę lotu czy robisz roczne podsumowanie podróży, TripReel sprawia, że przekształcenie wspomnień w filmy do udostępnienia jest bezwysiłkowe.",ideas:{yearRecap:{title:"Podsumowanie podróży 2025",description:"Automatycznie stwórz swoje roczne podsumowanie podróży na 2025 rok"},europeRoadTrip:{title:"Europejski road trip",description:"Pokaż swoją europejską przygodę z animowanymi mapami tras"},southeastAsia:{title:"Podróż po Azji Południowo-Wschodniej",description:"Zwizualizuj swoją trasę z plecakiem przez wiele krajów"},japanRail:{title:"Podróż pociągiem po Japonii",description:"Twórz wideo map tras pociągowych po Japonii"},crossCountry:{title:"Przez całe USA",description:"Zamień swój amerykański road trip w epicki film trasy"},islandHopping:{title:"Skakanie po wyspach",description:"Pokaż swoje podróże z wyspy na wyspę ze wspaniałymi animacjami 3D"},worldTour:{title:"Montaż podróży dookoła świata",description:"Wiele podróży w jednym niesamowitym filmie globalnej podróży"},travelPlans:{title:"Plany podróży na 2026",description:"Zwizualizuj i zaplanuj swoje ekscytujące przygody podróżnicze na 2026 rok"},lifetimeTravel:{title:"Historia podróży życia",description:"Stwórz wideo pokazujące wszystkie Twoje życiowe podróże"},regionalExplorer:{title:"Regionalny odkrywca",description:"Nakreśl swoje przygody przez stany, prowincje i regiony"},festivalCircuit:{title:"Obwód festiwali",description:"Nakreśl swoją podróż po festiwalach muzycznych i wydarzeniach"},bikeRoutes:{title:"Moje miejskie wycieczki",description:"Pokaż wszystkie swoje miejskie wypady"}}},s={title:"Aplikacja",subtitle:"Dostępna już w App Store",alt1:"Automatyczne filmy podróżnicze - Twórz wspaniałe filmy w sekundach",alt2:"Wykrywanie lokalizacji zdjęć - Wykorzystuje metadane Twoich zdjęć",alt3:"Wykrywanie podróży - Automatycznie grupuje Twoje podróże",alt4:"Piękne filmy globusa - Animacja globusa Twojej podróży",alt5:"Własne style - Personalizuj swoje filmy podróżnicze"},z={comingSoon:"Wkrótce",androidTitle:"Aplikacja na Androida wkrótce!",androidMessage:'Wersja na Androida nie jest jeszcze dostępna, ale będzie wkrótce. Napisz do mnie na <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a>, a dam Ci znać, gdy będzie gotowa!',gotIt:"Rozumiem!"},p={title:"Najczęściej zadawane pytania",subtitle:"Wszystko, co musisz wiedzieć o TripReel",q1:{question:"Czy mogę naprawdę korzystać z aplikacji w pełni w trybie samolotowym?",answer:"Tak! Dla użytkowników premium aplikacja może być używana całkowicie offline w trybie samolotowym bez żadnych ograniczeń. Dla użytkowników bez premium niektóre funkcje są wspierane reklamami, które mogą wymagać czasowego włączenia Internetu, ale dla użytkowników premium nie ma reklam i aplikacja może być w pełni używana w trybie samolotowym."},q2:{question:"Zaktualizowałem do Premium, jak mogę usunąć znak wodny?",answer:"Wiele osób pyta, jaka aplikacja została użyta do stworzenia tych filmów, więc po aktualizacji do premium masz opcję dodania mniejszej wersji znaku wodnego (tylko z nazwą aplikacji) lub całkowitego usunięcia go, jeśli chcesz."},q3:{question:"Czy moje dane ze zdjęć są bezpieczne i prywatne?",answer:"Absolutnie! TripReel czyta tylko metadane lokalizacji z Twoich zdjęć - nigdy nie uzyskujemy dostępu, nie przechowujemy ani nie przesyłamy rzeczywistej zawartości zdjęć. Całe przetwarzanie odbywa się lokalnie na Twoim urządzeniu i żadne dane nigdy nie opuszczają Twojego telefonu. Możesz to sprawdzić, używając aplikacji w trybie samolotowym - działa doskonale offline!"},q4:{question:"Co jeśli moje zdjęcia nie mają danych lokalizacji?",answer:"Nie ma problemu! Jeśli usługi lokalizacji nie były włączone, gdy robiłeś zdjęcia, możesz ręcznie tworzyć podróże i dodawać lokalizacje samodzielnie. Aplikacja daje Ci pełną kontrolę nad dostosowaniem Twojej osi czasu podróży."},q5:{question:"Jak aplikacja automatycznie wykrywa moje podróże?",answer:"TripReel analizuje metadane lokalizacji i znaczniki czasu z Twoich zdjęć, aby inteligentnie zidentyfikować, kiedy i gdzie podróżowałeś. Grupuje bliskie lokalizacje i daty razem, aby automatycznie wykryć Twoje podróże bez jakiejkolwiek ręcznej pracy."},q6:{question:"Czy mogę dostosować wygląd moich filmów?",answer:"Tak! Możesz wybrać spośród wielu stylów globusa i dostosować różne aspekty swoich animowanych filmów podróżniczych, aby pasowały do Twojej osobistej estetyki. Użytkownicy premium uzyskują dostęp do dodatkowych stylów animacji tras, motywów map i opcji tras lotów."},q7:{question:"Czy muszę utworzyć konto?",answer:"Nie potrzebujesz konta! TripReel działa natychmiast po pobraniu. Nie ma rejestracji, logowania ani potrzeby podawania danych osobowych. Po prostu pobierz aplikację i zacznij tworzyć swoje filmy podróżnicze od razu."},q8:{question:"Dlaczego w mojej podróży brakuje lokalizacji?",answer:"Aplikacja może pracować tylko z dostępnymi danymi, więc po pierwsze potrzebujesz przynajmniej kilku zdjęć w tej lokalizacji. Po drugie musisz upewnić się, że miałeś włączone dane lokalizacji, gdy tam byłeś. Po trzecie czasami słaby odbiór GPS może powodować nieprawidłowe dane lokalizacji. Jeśli wykluczyłeś to wszystko, a Twoja lokalizacja nadal się nie wyświetla, możesz ręcznie dodać tę lokalizację z Przegląd podróży > przycisk Edytuj. Użyj również Kontakt, aby zgłosić problem."},q9:{question:"Gdzie mogę udostępnić swój wspaniały film?",answer:"Oczywiście możesz też udostępnić go na wszystkich platformach społecznościowych. Aby lepiej pasował do platformy, aplikacja umożliwia różne proporcje obrazu dla Twoich filmów."},q10:{question:"Gdzie mogę zgłosić błąd?",answer:"Po prostu skontaktuj się ze mną bezpośrednio pod adresem marian@qod.ee, krótko wyjaśniając, na czym polega problem."}},c={title:"Wsparcie email",description:"Jeśli masz jakieś uwagi lub napotkasz jakiekolwiek problemy, skontaktuj się ze mną bezpośrednio pod tym adresem email, a osobiście przeczytam i zajmę się Twoim zapytaniem tak szybko, jak to możliwe. Dziękuję za korzystanie z aplikacji!",close:"Zamknij"},w={default:{title:"🍪 Ciasteczka",message:"Używamy ciasteczek na stronie TripReel, aby poprawić Twoje doświadczenie. Nie zbieramy danych osobowych.",accept:"Akceptuj",decline:"Odrzuć",details:"Szczegóły"},theme:{title:"🍪 Ciasteczka",message:"🌙 Aby zapisać preferencje motywu, musisz zaakceptować niezbędne ciasteczka na stronie TripReel. Bez nich Twój wybór motywu nie może być zapisany.",accept:"Akceptuj",decline:"Odrzuć",details:"Szczegóły"}},y={privacy:"Polityka prywatności aplikacji",cookies:"Polityka ciasteczek strony",contact:"Kontakt",cookiePreferences:"Preferencje ciasteczek",madeWith:"Stworzone z",forTravelers:"dla podróżników na całym świecie",copyright:"© {{year}} TripReel."},l={title:"Gotowy, aby podzielić się swoją podróżą?",description:"Pobierz TripReel dzisiaj i przekształć swój aparat w piękne filmy podróżnicze z animowanymi mapami i trasami. Twoje przygody zasługują na to, aby je świętować.",features:"Darmowe pobieranie • Szybkie i wygodne • Prywatność gwarantowana"},d={meta:a,header:i,hero:e,howItWorks:o,videoSection:t,features:n,videoIdeas:r,screenshots:s,appStore:z,faq:p,contact:c,cookieBanner:w,footer:y,cta:l};export{z as appStore,c as contact,w as cookieBanner,l as cta,d as default,p as faq,n as features,y as footer,i as header,e as hero,o as howItWorks,a as meta,s as screenshots,r as videoIdeas,t as videoSection};
